#include <gdk-pixbuf/gdk-pixbuf.h>
#include <stdio.h>
int main(int argc,char **argv) { GError *err=NULL; GdkPixbuf *p=gdk_pixbuf_new_from_file(argv[1],&err); if(!p){fprintf(stderr,"%s",err->message);return 1;} int w=gdk_pixbuf_get_width(p),h=gdk_pixbuf_get_height(p),n=gdk_pixbuf_get_n_channels(p),s=gdk_pixbuf_get_rowstride(p);guchar *data=gdk_pixbuf_get_pixels(p);FILE *f=fopen(argv[2],"wb");for(int y=0;y<h;y++)for(int x=0;x<w;x++){guchar *c=data+y*s+x*n;fwrite(c,1,3,f);guchar a=n==4?c[3]:255;fwrite(&a,1,1,f);}fclose(f);printf("%d %d\n",w,h); if(argc>3)gdk_pixbuf_save(p,argv[3],"png",&err,NULL);g_object_unref(p);return 0;}
